H.background();
const z = Math.max(1, Math.round(P.z));
H.text("Redox half-reactions: balance the electrons transferred", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Oxidation loses e- (number goes up); reduction gains e-; the two e- counts must match.", 24, 52, { color: H.colors.sub, size: 13 });

const oxX = 180, redX = 720;
H.rect(oxX - 50, 120, 100, 220, { fill: H.colors.panel, stroke: H.colors.accent, width: 2, radius: 6 });
H.rect(redX - 50, 120, 100, 220, { fill: H.colors.panel, stroke: H.colors.good, width: 2, radius: 6 });
H.text("OXIDATION", oxX, 108, { color: H.colors.accent, size: 13, weight: 700, align: "center" });
H.text("REDUCTION", redX, 108, { color: H.colors.good, size: 13, weight: 700, align: "center" });
H.text("M -> M(" + z + "+) + " + z + " e-", oxX, 360, { color: H.colors.accent, size: 14, weight: 700, align: "center" });
H.text("X(" + z + "+) + " + z + " e- -> X", redX, 360, { color: H.colors.good, size: 14, weight: 700, align: "center" });

const wireY = 150;
H.line(oxX, 120, oxX, wireY, { color: H.colors.sub, width: 2 });
H.line(redX, 120, redX, wireY, { color: H.colors.sub, width: 2 });
H.line(oxX, wireY, redX, wireY, { color: H.colors.sub, width: 2 });
H.arrow(oxX + 200, wireY, oxX + 260, wireY, { color: H.colors.yellow, width: 2 });

for (let i = 0; i < z; i++) {
  const phase = (t * 0.5 + i / z) % 1;
  const ex = oxX + (redX - oxX) * phase;
  H.circle(ex, wireY, 7, { fill: H.colors.yellow, stroke: H.colors.ink, width: 1 });
  H.text("-", ex, wireY, { color: H.colors.bg, size: 11, weight: 700, align: "center", baseline: "middle" });
}

H.text("Oxidation state of M: 0  ->  +" + z, 24, 410, { color: H.colors.accent, size: 13 });
H.text("Oxidation state of X: +" + z + "  ->  0", 24, 432, { color: H.colors.good, size: 13 });
H.text("Electrons transferred = " + z + " per atom", 24, 462, { color: H.colors.accent2, size: 16, weight: 700 });
